import{_ as s,o as n,c as a,ag as r}from"./chunks/framework.C15dTZqp.js";const m=JSON.parse(`{"title":"Cheat sheet : 7 réflexes pour lundi matin","description":"","frontmatter":{},"headers":[],"relativePath":"handout-09-cheat-sheet.md","filePath":"handout-09-cheat-sheet.md","handout":{"fichier":"handout-09-cheat-sheet.md","markdown":"# Handout — Cheat sheet : 7 réflexes pour lundi matin\\n\\n**Speed training IA · Zenika · fiche mémo**\\n\\nUne page à garder sous la main.\\n\\n## Les 7 réflexes\\n\\n1. **Relancer** avant de faire confiance : une réponse est une proposition.\\n2. Écrire sa demande avec les **4 ingrédients** (rôle, sortie attendue, règles, à éviter)… et transformer ce qui marche en **skill** ou assistant d'équipe.\\n3. Faire produire une **structure**, la valider, puis demander le livrable, **avec un exemple** du format attendu.\\n4. **Repartir proprement** quand la session dérive : rewind si ça part mal dès le début, nouvelle session et note de cadrage si une longue session dérive.\\n5. **Extraire** décisions, risques et actions avant de fermer, et relire l'extraction.\\n6. En discovery : **interviewer sur des faits**, prototyper **lo-fi**, **tester** avec de vrais utilisateurs.\\n7. **Pas de données sensibles** hors des versions entreprise des assistants, et un **humain qui valide** avant d'agir.\\n\\n## La boucle\\n\\n**Tester** (relancer, comparer) → **Structurer** (4 ingrédients, brief validé) → **Cadrer le contexte** (note de cadrage, bons documents, session propre) → **Capitaliser** (artefacts) → on repart sur une base propre.\\n\\nÀ chaque étape : **choisir ce qu'on donne** au modèle, **relire avec un œil humain**.\\n\\n## Les questions à se poser\\n\\n- La sortie varie beaucoup ? → _Qu'est-ce que je n'ai pas cadré ?_\\n- La session s'allonge ? → _Tout ce qui reste ici aide-t-il encore la tâche du jour ?_\\n- L'IA cite un chiffre ? → _D'où vient-il ? Est-il dans mes sources ?_\\n- Je colle un document ? → _L'enverrais-je par email à un inconnu ?_\\n- L'IA va agir à ma place ? → _Qui signe si c'est faux ?_\\n\\n## Le modèle de demande\\n\\n\`\`\`text\\nTu es [rôle], tu travailles sur [sujet].\\nProduis [livrable], au format [structure, longueur].\\nRègles : [cible, contraintes, éléments obligatoires].\\nÀ éviter : [ce qu'il ne faut pas inventer ou inclure].\\nExemple du format attendu : [un exemple court].\\n\`\`\`\\n"}}`),t={name:"handout-09-cheat-sheet.md"};function i(o,e,l,u,d,c){return n(),a("div",null,[...e[0]||(e[0]=[r("",12)])])}const h=s(t,[["render",i]]);export{m as __pageData,h as default};
